#let benchmark_results_table() = {
  let data = bench_data()
  let meta = data.meta
  let dirty_tag = if "dirty" in meta and meta.dirty { [ · 工作树已修改] } else { [] }
  let rows = benchmark_rows().map(((label, sub, wl, has_model)) => {
    let sib = bench_find(data, "sibuna", sub, wl)
    let model = none
    (
      [#label],
      [#fmt_ns(if sib != none { sib.ns_per_op_median } else { none })],
      [#fmt_ns(if sib != none { sib.ns_per_op_min } else { none }) – #fmt_ns(if sib != none { sib.ns_per_op_max } else { none })],
      [#fmt_int(if sib != none { sib.ops_per_sec } else { none })],
    )
  }).flatten()
  let naive = bench_find(data, "sibuna-naive", "bot_matcher", "sequential_substring_40_signatures")
  let ac = bench_find(data, "sibuna", "bot_matcher", "aho_corasick_40_signatures")
  [
    #text(size: 8pt, fill: gray)[
      记录日期 #meta.date · #meta.host · #meta.cpu · #meta.os · 版本提交
      #raw(meta.git)#dirty_tag · Zig #meta.zig · ReleaseFast · 7 批次，中位数及最小–最大值范围
    ]
    #v(6pt)
    #grid(
      columns: (1fr, 1fr, 1fr, 1fr),
      gutter: 6pt,
      stat_tile([#fmt_ns(bench_find(data, "sibuna", "pow_verify", "hashcash_16_bits").ns_per_op_median)], [Hashcash 验证],
        [硬件 SHA-256，无内存分配], fill: blue_light, stroke: blue),
      stat_tile([#fmt_ns(bench_find(data, "sibuna", "token_auth", "blake3_mac_token").ns_per_op_median)], [会话令牌检查],
        [带密钥的 BLAKE3，75 字符 Cookie], fill: green_light, stroke: green),
      stat_tile([#calc.round(meta.idle_rss_kb / 1024, digits: 1) MiB], [空闲常驻内存],
        [守护进程启动后，存储关闭], fill: amber_light, stroke: amber),
      stat_tile([#calc.round(meta.binary_bytes / 1048576, digits: 1) MiB], [守护进程二进制],
        [WASM 求解器 #meta.wasm_bytes 字节], fill: rgb("f5f3ff"), stroke: rgb("7c3aed")),
    )
    #v(8pt)
    #block(width: 100%, inset: 10pt, radius: 5pt, fill: blue_light, stroke: 0.5pt + rule)[
      #text(size: 11pt, weight: "bold")[每次操作的实测延迟]
      #linebreak()
      #text(size: 8pt, fill: gray)[仅展示基础操作的实测延迟。未对内存分配活动进行测量。]
      #v(5pt)
      #table(
        columns: (1.6fr, 0.8fr, 1fr, 0.8fr),
        table.header([*负载*], [*中位数*], [*范围*], [*ops/s*]),
        ..rows,
      )
      #v(4pt)
      #text(size: 8pt, fill: gray)[作为对照，同一主机上以顺序子串搜索扫描相同的 40 个机器人特征耗时 #fmt_ns(naive.ns_per_op_median)，自动机耗时 #fmt_ns(ac.ns_per_op_median)。]
    ]
  ]
}

